inline std::string_view tariffHintMessageKeyName(TariffHintMessageKey key){
    static constexpr std::array<std::string_view,tariffHintMessageKeyCount> names={{"tariff.hint.tiers","tariff.hint.time_mode","tariff.hint.clock_kind","tariff.hint.date","tariff.hint.optional_decimal","tariff.hint.utc_ms","tariff.hint.opening","tariff.hint.mask","tariff.hint.fixed_offset","tariff.hint.minute","tariff.hint.default"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage tariffHintMessage(std::string_view language,TariffHintMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=tariffHintMessageKeyCount)return {};
    const auto &source=tariffHintLocalePacks()[0];const auto *selected=&source;for(const auto &pack:tariffHintLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string tariffHintEnglish(TariffHintMessageKey key){return std::string(tariffHintMessage("en",key).text);}
